package goemit

// internalTTYRuntime adapts internal/tty.ts color-depth detection.
const internalTTYRuntime = `
var tsInternalTTYWarning struct { sync.Mutex; warned bool }
func tsInternalTTYEnv(loop *tsLoop,env tsValue,name string)tsValue{return tsGet(loop,env,tsStringReference(tsStringUTF8(name)))}
func tsInternalTTYHas(env tsValue,name string)bool{return tsHas(env,tsStringReference(tsStringUTF8(name)))}
func tsInternalTTYWarn(loop *tsLoop,env tsValue){
	tsInternalTTYWarning.Lock();if tsInternalTTYWarning.warned{tsInternalTTYWarning.Unlock();return};names:=[]string{};if v:=tsInternalTTYEnv(loop,env,"NODE_DISABLE_COLORS");!tsIsUndefined(v)&&tsText(v)!=""{names=append(names,"NODE_DISABLE_COLORS")};if v:=tsInternalTTYEnv(loop,env,"NO_COLOR");!tsIsUndefined(v)&&tsText(v)!=""{names=append(names,"NO_COLOR")};if len(names)==0{tsInternalTTYWarning.Unlock();return};tsInternalTTYWarning.warned=true;tsInternalTTYWarning.Unlock();name:=strings.Join(names,"' and '");process:=tsNodeProcessModule(loop);emit:=tsGet(loop,process,tsStringReference(tsStringUTF8("emitWarning")));tsCall(loop,emit,tsStringReference(tsStringUTF8("The '"+name+"' env is ignored due to the 'FORCE_COLOR' env being set.")),tsStringReference(tsStringUTF8("Warning")))
}
func tsInternalTTYGetColorDepth(loop *tsLoop,env tsValue)tsValue{
	const(c2=1;c16=4;c256=8;c16m=24)
	force:=tsInternalTTYEnv(loop,env,"FORCE_COLOR");if !tsIsUndefined(force){switch tsText(force){case "","1","true":tsInternalTTYWarn(loop,env);return tsNumberValue(c16);case "2":tsInternalTTYWarn(loop,env);return tsNumberValue(c256);case "3":tsInternalTTYWarn(loop,env);return tsNumberValue(c16m);default:return tsNumberValue(c2)}}
	for _,name:=range []string{"NODE_DISABLE_COLORS","NO_COLOR"}{if v:=tsInternalTTYEnv(loop,env,name);!tsIsUndefined(v)&&tsText(v)!=""{return tsNumberValue(c2)}};if tsText(tsInternalTTYEnv(loop,env,"TERM"))=="dumb"{return tsNumberValue(c2)}
	process:=tsNodeProcessModule(loop);if tsText(tsGet(loop,process,tsStringReference(tsStringUTF8("platform"))))=="win32"{osModule:=tsNodeOSModule();release:=tsText(tsGet(loop,osModule,tsStringReference(tsStringUTF8("release"))));parts:=strings.Split(release,".");if len(parts)>=3{major,_:=strconv.Atoi(parts[0]);build,_:=strconv.Atoi(parts[2]);if major>=10{if build>=14931{return tsNumberValue(c16m)};if build>=10586{return tsNumberValue(c256)}}};return tsNumberValue(c16)}
	if !tsIsUndefined(tsInternalTTYEnv(loop,env,"TMUX"))&&tsText(tsInternalTTYEnv(loop,env,"TMUX"))!=""{return tsNumberValue(c16m)};if tsInternalTTYHas(env,"TF_BUILD")&&tsInternalTTYHas(env,"AGENT_NAME"){return tsNumberValue(c16)}
	if tsInternalTTYHas(env,"CI"){for _,name:=range []string{"APPVEYOR","BUILDKITE","CIRCLECI","DRONE","GITEA_ACTIONS","GITHUB_ACTIONS","GITLAB_CI","TRAVIS"}{if !tsInternalTTYHas(env,name){continue};switch name{case "CIRCLECI","GITEA_ACTIONS","GITHUB_ACTIONS":return tsNumberValue(c16m);case "APPVEYOR","BUILDKITE","DRONE","GITLAB_CI","TRAVIS":return tsNumberValue(c256)}};if tsText(tsInternalTTYEnv(loop,env,"CI_NAME"))=="codeship"{return tsNumberValue(c256)};return tsNumberValue(c2)}
	if tsInternalTTYHas(env,"TEAMCITY_VERSION"){version:=tsText(tsInternalTTYEnv(loop,env,"TEAMCITY_VERSION"));parts:=strings.Split(version,".");if len(parts)>1{major,_:=strconv.Atoi(parts[0]);minor,_:=strconv.Atoi(strings.TrimLeft(parts[1],"0"));if major>=10||major==9&&minor>=1{return tsNumberValue(c16)}};return tsNumberValue(c2)}
	switch tsText(tsInternalTTYEnv(loop,env,"TERM_PROGRAM")){case "iTerm.app":version:=tsText(tsInternalTTYEnv(loop,env,"TERM_PROGRAM_VERSION"));if version==""||strings.HasPrefix(version,"0.")||strings.HasPrefix(version,"1.")||strings.HasPrefix(version,"2."){return tsNumberValue(c256)};return tsNumberValue(c16m);case "HyperTerm","ghostty","WezTerm","MacTerm":return tsNumberValue(c16m);case "Apple_Terminal":return tsNumberValue(c256)}
	colorTerm:=tsText(tsInternalTTYEnv(loop,env,"COLORTERM"));if colorTerm=="truecolor"||colorTerm=="24bit"{return tsNumberValue(c16m)}
	term:=tsText(tsInternalTTYEnv(loop,env,"TERM"));lower:=strings.ToLower(term);if strings.Contains(lower,"truecolor"){return tsNumberValue(c16m)};if strings.HasPrefix(lower,"xterm-256"){return tsNumberValue(c256)}
	for _,name:=range []string{"eterm","cons25","console","cygwin","dtterm","gnome","hurd","jfbterm","konsole","kterm","mlterm","mosh","putty","st","rxvt-unicode-24bit","terminator","xterm-kitty"}{if lower==name{if name=="mosh"||name=="rxvt-unicode-24bit"||name=="terminator"||name=="xterm-kitty"{return tsNumberValue(c16m)};return tsNumberValue(c16)}}
	for _,prefix:=range []string{"rxvt","screen","xterm","vt100","vt220"}{if strings.HasPrefix(lower,prefix){return tsNumberValue(c16)}};if strings.Contains(lower,"ansi")||strings.Contains(lower,"color")||strings.Contains(lower,"linux")||strings.Contains(lower,"direct")||strings.HasPrefix(lower,"con")&&strings.Contains(lower,"x"){return tsNumberValue(c16)};if colorTerm!=""{return tsNumberValue(c16)};return tsNumberValue(c2)
}
func tsInternalTTYModule(loop *tsLoop)tsValue{out:=tsNewObject();out.set("getColorDepth",tsNamedNativeMethod("getColorDepth",1,func(loop *tsLoop,_ tsValue,args ...tsValue)tsValue{env:=tsArg(args,0);if tsIsUndefined(env){env=tsGet(loop,tsNodeProcessModule(loop),tsStringReference(tsStringUTF8("env")))};return tsInternalTTYGetColorDepth(loop,env)}));out.set("default",tsObjectValue(out));return tsObjectValue(out)}
`
